        v = np.random.uniform(lb, ub, size=dim)

        # Mutation
        u = np.copy(x_best)
        for i in range(dim):
            if rng.random() < 0.5:
                u[i] += (ub - lb) * rng.uniform(-1, 1)

        # Crossover
        v_ = 0.7 * v + 0.3 * x_best

        # Selection
        f_v = func(v_)
